def is_var(t):
    return isinstance(t, str) and t[:1].islower() and t.isalnum()


def unify(a, b):
    """Return a substitution dict, or raise ValueError on clash / occurs."""
    if a == b:
        return {}
    if is_var(a):
        return {a: b}
    if is_var(b):
        return {b: a}
    if isinstance(a, tuple) and isinstance(b, tuple) and a[0] == b[0] and len(a) == len(b):
        return {}
    raise ValueError("clash")

