import pytest

from unify import unify


def test_var_binds():
    assert unify("a", "int") == {"a": "int"}


def test_function_args():
    # ('->', a, b)  ~  ('->', 'int', 'int')
    s = unify(("->", "a", "b"), ("->", "int", "int"))
    assert s["a"] == "int"
    assert s["b"] == "int"


def test_nested():
    s = unify(("->", "a", ("->", "b", "a")), ("->", "int", ("->", "bool", "int")))
    assert s["a"] == "int"
    assert s["b"] == "bool"


def test_occurs():
    with pytest.raises(ValueError):
        unify("a", ("->", "a", "int"))


def test_compose():
    # unifying (a -> a) with (b -> int) must force a=int and b=int
    s = unify(("->", "a", "a"), ("->", "b", "int"))
    assert apply(s, "a") == "int"
    assert apply(s, "b") == "int"


def apply(subst, t):
    seen = set()
    while is_var(t) and t in subst and t not in seen:
        seen.add(t)
        t = subst[t]
    if isinstance(t, tuple):
        return (t[0],) + tuple(apply(subst, x) for x in t[1:])
    return t


def is_var(t):
    return isinstance(t, str) and t[:1].islower() and t.isalnum()
